const listConversationsForMember = `-- name: ListConversationsForMember :many
SELECT c.id, c.workspace_id, c.kind, c.name, c.about, c.visibility, c.direct_key, c.parent_conversation_id, c.root_message_id, c.created_by, c.last_message_seq, c.last_message_at, c.archived_at, c.created_at, c.updated_at,
       COALESCE(cm.last_read_seq, 0)::bigint AS my_last_read_seq,
       (cm.conversation_id IS NOT NULL)::bool AS is_member
FROM conversation c
LEFT JOIN conversation_member cm
  ON cm.conversation_id = c.id AND cm.member_type = 'member' AND cm.member_id = $1
WHERE c.workspace_id = $2
  AND c.kind IN ('channel', 'direct')
  AND (cm.conversation_id IS NOT NULL OR (c.kind = 'channel' AND c.visibility = 'public'))
ORDER BY c.kind, lower(c.name), c.created_at
`

type ListConversationsForMemberParams struct {
	UserID      pgtype.UUID `json:"user_id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

type ListConversationsForMemberRow struct {
	ID                   pgtype.UUID        `json:"id"`
	WorkspaceID          pgtype.UUID        `json:"workspace_id"`
	Kind                 string             `json:"kind"`
	Name                 string             `json:"name"`
	About                string             `json:"about"`
	Visibility           string             `json:"visibility"`
	DirectKey            pgtype.Text        `json:"direct_key"`
	ParentConversationID pgtype.UUID        `json:"parent_conversation_id"`
	RootMessageID        pgtype.UUID        `json:"root_message_id"`
	CreatedBy            pgtype.UUID        `json:"created_by"`
	LastMessageSeq       int64              `json:"last_message_seq"`
	LastMessageAt        pgtype.Timestamptz `json:"last_message_at"`
	ArchivedAt           pgtype.Timestamptz `json:"archived_at"`
	CreatedAt            pgtype.Timestamptz `json:"created_at"`
	UpdatedAt            pgtype.Timestamptz `json:"updated_at"`
	MyLastReadSeq        int64              `json:"my_last_read_seq"`
	IsMember             bool               `json:"is_member"`
}

// The channels and direct conversations a member sees: every public channel in
// the workspace, plus every private channel and direct conversation they are
// in. my_last_read_seq is 0 for a public channel they have not joined.
func (q *Queries) ListConversationsForMember(ctx context.Context, arg ListConversationsForMemberParams) ([]ListConversationsForMemberRow, error) {
	rows, err := q.db.Query(ctx, listConversationsForMember, arg.UserID, arg.WorkspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListConversationsForMemberRow{}
	for rows.Next() {
		var i ListConversationsForMemberRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Kind,
			&i.Name,
			&i.About,
			&i.Visibility,
			&i.DirectKey,
			&i.ParentConversationID,
			&i.RootMessageID,
			&i.CreatedBy,
			&i.LastMessageSeq,
			&i.LastMessageAt,
			&i.ArchivedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.MyLastReadSeq,
			&i.IsMember,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const markConversationRead = `-- name: MarkConversationRead :exec
UPDATE conversation_member
SET last_read_seq = GREATEST(last_read_seq, LEAST($1::bigint, (SELECT last_message_seq FROM conversation WHERE id = $2)))
WHERE conversation_id = $2 AND member_type = 'member' AND member_id = $3
`

type MarkConversationReadParams struct {
	Seq            int64       `json:"seq"`
	ConversationID pgtype.UUID `json:"conversation_id"`
	UserID         pgtype.UUID `json:"user_id"`
}

func (q *Queries) MarkConversationRead(ctx context.Context, arg MarkConversationReadParams) error {
	_, err := q.db.Exec(ctx, markConversationRead, arg.Seq, arg.ConversationID, arg.UserID)
	return err
}

const nextConversationMessageSeq = `-- name: NextConversationMessageSeq :one
UPDATE conversation
SET last_message_seq = last_message_seq + 1, last_message_at = now(), updated_at = now()
WHERE id = $1
RETURNING last_message_seq
`

// Takes the conversation's row lock for the rest of the transaction, so seq is
// gapless and messages commit in seq order.
func (q *Queries) NextConversationMessageSeq(ctx context.Context, id pgtype.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, nextConversationMessageSeq, id)
	var last_message_seq int64
	err := row.Scan(&last_message_seq)
	return last_message_seq, err
}

